defmodule AtlasFlowContract.GoldenTest do
  use ExUnit.Case, async: true

  alias AtlasFlowGenerator.{Atlas, Rela}

  # A component reading the committed target, as a running one would.
  defmodule Committed do
    use AtlasFlowGenerator.Runtime, target: "../../targets/atlas/flows.json"
  end

  # test/golden/issue.flows.yaml is the approved Issue flow (the design's
  # input-definitions/issue.flows.yaml, copied unchanged). Rela gives it this version;
  # a run keeps the version it started with, so the generated file must keep it too.
  @version "5e2320f6db243534"

  defp below_header(text),
    do: text |> String.split("\n") |> Enum.drop_while(&(&1 =~ ~r/^#/)) |> Enum.join("\n")

  defp generated, do: Rela.flows_yaml(AtlasFlowContract.Issue.__flows__())

  test "Issue's flows.yaml is byte-identical to the approved file below the header" do
    assert generated() == below_header(File.read!("test/golden/issue.flows.yaml"))
  end

  test "the committed target holds it, and its diagram shows the same version" do
    assert below_header(File.read!("../targets/rela/flows.yaml")) == generated()
    assert File.read!("../targets/diagrams/issue.md") =~ "Rela flow version: `#{@version}`"
  end

  test "the committed flows.json is what the writer gives for Issue and every gate" do
    [open, header | rest] = String.split(File.read!("../targets/atlas/flows.json"), "\n")
    assert header =~ ~s(  "_generated": "Generated by atlas)
    assert header =~ "flow/contract/lib/issue.ex, flow/contract/lib/gates.ex"

    assert Enum.join([open | rest], "\n") ==
             Atlas.flows_json(
               AtlasFlowContract.Issue.__flows__(),
               AtlasFlowContract.Gates.__gates__(),
               Committed.rela_flows_sha256()
             )
  end

  test "the committed flows.json is bound to the committed flows.yaml" do
    assert Committed.check_rela_flows(File.read!("../targets/rela/flows.yaml")) == :ok
    assert {:error, _} = Committed.check_rela_flows(File.read!("test/golden/issue.flows.yaml"))
  end

  test "a running component reads Issue's mechanisms and the gates, integrate included" do
    states = Committed.flows()["issue"]["states"]
    assert states["delivery_gate"]["spec"] == %{"gate" => "delivery_evidence", "version" => 1}
    assert states["in_pr"] == %{"final" => false, "label" => "In pull request"}

    assert %{"flavor" => "rule", "purpose" => "flow", "rule" => %{"all" => [_, _, _]}} =
             Committed.gates()["integrate"]

    assert Map.keys(Committed.gates()) == ["delivery_evidence", "integrate", "review"]
  end

  @tag :rela
  test "the pinned rela finds it valid, with the approved version" do
    bin = Path.join(System.fetch_env!("ATLAS_RELA_BIN"), "rela")
    flows = AtlasFlowContract.Issue.__flows__()
    yaml = File.read!("../targets/rela/flows.yaml")
    assert {:ok, [%{"name" => "issue", "version" => @version}]} = Rela.check(bin, yaml, flows)
  end
end
